static const char* const AI_SHUFFLE_SHADER =
"#version 300 es\n"
"precision highp float;\n"
"precision highp int;\n"
"uniform highp sampler2D src;\n"
"uniform highp sampler2D c0;\n"
"uniform highp sampler2D c1;\n"
"uniform highp sampler2D c2;\n"
"uniform highp sampler2D c3;\n"
"uniform highp sampler2D c4;\n"
"uniform highp sampler2D c5;\n"
"uniform highp sampler2D c6;\n"
"uniform highp sampler2D c7;\n"
"uniform highp sampler2D c8;\n"
"uniform highp sampler2D c9;\n"
"uniform highp sampler2D c10;\n"
"uniform highp sampler2D c11;\n"
"out vec4 color;\n"
"float pick(vec4 v, int k) { return k == 0 ? v.x : (k == 1 ? v.y : (k == 2 ? v.z : v.w)); }\n"
"void main() {\n"
"  ivec2 q = ivec2(gl_FragCoord.xy);\n"
"  ivec2 p = q / 4;\n"
"  int row = q.y - p.y * 4;\n"
"  int col = q.x - p.x * 4;\n"
"  vec4 r, g, b;\n"
"  if (row == 0) { r = texelFetch(c0, p, 0); g = texelFetch(c4, p, 0); b = texelFetch(c8, p, 0); }\n"
"  else if (row == 1) { r = texelFetch(c1, p, 0); g = texelFetch(c5, p, 0); b = texelFetch(c9, p, 0); }\n"
"  else if (row == 2) { r = texelFetch(c2, p, 0); g = texelFetch(c6, p, 0); b = texelFetch(c10, p, 0); }\n"
"  else { r = texelFetch(c3, p, 0); g = texelFetch(c7, p, 0); b = texelFetch(c11, p, 0); }\n"
"  vec3 base = texelFetch(src, p, 0).rgb;\n"
"  color = vec4(clamp(base + vec3(pick(r, col), pick(g, col), pick(b, col)), 0.0, 1.0), 1.0);\n"
"}\n";
